<?php
$type=get_query_var('post_type'); if(is_array($type)) $type=reset($type);
$is_notices=is_category('obavjestenja');
if($type==='mf_staff') {
    matinf_theme_heading('Ljudi koji prenose znanje.','Upoznajte rukovodioce, nastavnike i saradnike. Pronađite njihov profil, predmete i kontakt.','NASTAVNO OSOBLJE');
    $groups=['rukovodioci'=>'Rukovodioci','nastavnici'=>'Nastavnici','saradnici'=>'Saradnici'];
    $selected=isset($_GET['group']) && is_string($_GET['group']) ? sanitize_key($_GET['group']) : ''; if(!isset($groups[$selected])) $selected='';
    $people=get_posts(['post_type'=>'mf_staff','post_status'=>'publish','has_password'=>false,'numberposts'=>-1,'orderby'=>'title','order'=>'ASC']); ?>
    <nav class="pill-nav" aria-label="Grupe osoblja"><a <?php echo !$selected?'aria-current="page"':''; ?> href="<?php echo esc_url(get_post_type_archive_link('mf_staff')); ?>">Svi</a><?php foreach($groups as $key=>$label) : ?><a <?php echo $key===$selected?'aria-current="page"':''; ?> href="<?php echo esc_url(add_query_arg('group',$key,get_post_type_archive_link('mf_staff'))); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
    <?php foreach($groups as $key=>$label) { if($selected && $selected!==$key) continue; $members=array_filter($people,fn($p)=>matinf_staff_group($p->ID)===$label); if(!$members) continue;
        echo '<section class="directory-section" id="'.esc_attr($key).'"><div class="section-heading"><h2>'.esc_html($label).'</h2><span class="section-count">'.count($members).' profila</span></div><div class="people-grid">'; foreach($members as $person) matinf_theme_person($person); echo '</div></section>';
    } if(!$people) { echo '<p class="empty">Profili još nisu objavljeni.</p>'; }
} elseif($type==='mf_program') {
    matinf_theme_heading('Pronađite svoj studijski put.','Od prvih ideja do istraživanja i profesionalnog razvoja. Istražite programe po nivou studija.','STUDIJSKI PROGRAMI');
    $groups=matinf_program_groups(); ?>
    <nav class="pill-nav" aria-label="Nivoi studija"><?php foreach($groups as $key=>$group) : ?><a href="#<?php echo esc_attr($key); ?>"><?php echo esc_html($group['label']); ?></a><?php endforeach; ?></nav>
    <?php $symbols=['undergraduate'=>'∑','master'=>'{ }','doctoral'=>'π']; foreach($groups as $key=>$group) : ?>
    <section class="degree-section" id="<?php echo esc_attr($key); ?>"><div class="degree-intro"><span class="degree-symbol" aria-hidden="true"><?php echo $symbols[$key]??'∑'; ?></span><p class="eyebrow">VAŠ SLJEDEĆI KORAK</p><h2><?php echo esc_html($group['label']); ?></h2><p><?php echo esc_html(['undergraduate'=>'Izgradite temelje znanja i pronađite oblast koja vas pokreće.','master'=>'Produbite znanje i razvijajte svoju stručnu oblast.','doctoral'=>'Postavite nova pitanja i istražujte nove mogućnosti.'][$key]??'Istražite dostupne programe.'); ?></p></div><div class="degree-programs"><?php foreach($group['items'] as $program) { if(!matinf_is_public($program->ID,'mf_program')) continue; echo '<a class="degree-row" href="'.esc_url(get_permalink($program)).'"><div><span class="eyebrow">'.esc_html($group['label']).'</span><h3>'.esc_html($program->post_title).'</h3><p>'.(int)get_post_meta($program->ID,'_matinf_durationYears',true).' god. · '.(int)get_post_meta($program->ID,'_matinf_ects',true).' ECTS</p></div><span class="round-arrow" aria-hidden="true">↗</span></a>'; } if(!$group['items']) echo '<p class="empty">Programi još nisu objavljeni.</p>'; ?></div></section>
    <?php endforeach;
} elseif($type==='mf_course') {
    matinf_theme_heading('Predmeti, na jednom mjestu.','Izaberite program i godinu, zatim otvorite predmet za sadržaje, nastavnike i materijale.','NASTAVA I UČENJE'); ?>
    <form class="catalog-filters" method="get" action="<?php echo esc_url(get_post_type_archive_link('mf_course')); ?>"><label>Studijski program<select name="program_id"><option value="0">Svi programi</option><?php foreach(matinf_program_groups() as $group) { echo '<optgroup label="'.esc_attr($group['label']).'">'; foreach($group['items'] as $program) if(matinf_is_public($program->ID,'mf_program')) echo '<option value="'.$program->ID.'" '.selected(matinf_theme_int('program_id'),$program->ID,false).'>'.esc_html($program->post_title).'</option>'; echo '</optgroup>'; } ?></select></label><label>Godina<select name="study_year"><option value="0">Sve godine</option><?php for($i=1;$i<=4;$i++) echo '<option value="'.$i.'" '.selected(matinf_theme_int('study_year'),$i,false).'>'.$i.'. godina</option>'; ?></select></label><label>Semestar<select name="semester"><option value="0">Oba semestra</option><option value="1" <?php selected(matinf_theme_int('semester'),1); ?>>Zimski</option><option value="2" <?php selected(matinf_theme_int('semester'),2); ?>>Ljetni</option></select></label><button class="button">Prikaži predmete</button></form>
    <div class="course-directory"><?php while(have_posts()) : the_post(); $id=get_the_ID(); $pid=(int)get_post_meta($id,'_matinf_programId',true); ?><a class="course-row" href="<?php the_permalink(); ?>"><span class="course-year"><?php echo (int)get_post_meta($id,'_matinf_year',true); ?><small>GODINA</small></span><div><span class="eyebrow"><?php echo esc_html(matinf_is_public($pid,'mf_program')?get_the_title($pid):'Studijski program'); ?></span><h2><?php the_title(); ?></h2><p><?php echo (int)get_post_meta($id,'_matinf_semester',true); ?>. semestar · Sadržaj i materijali</p></div><span class="round-arrow" aria-hidden="true">↗</span></a><?php endwhile; if(!$GLOBALS['wp_query']->post_count) echo '<p class="empty">Nema predmeta za izabrane filtere. Promijenite program ili godinu.</p>'; ?></div><?php matinf_theme_pagination();
} elseif($type==='mf_document') {
    matinf_theme_heading('Dokumenti i materijali.','Nastavni planovi, obrasci i materijali dostupni za pregled i preuzimanje.','BIBLIOTEKA DOKUMENATA'); ?>
    <div class="resource-layout"><aside class="resource-intro"><span class="large-symbol" aria-hidden="true">↓</span><h2>Brzo do potrebnog dokumenta.</h2><p>Otvorite detalje za opis i povezane informacije ili pristupite dostupnoj datoteci.</p><a href="<?php echo esc_url(get_post_type_archive_link('mf_course')); ?>">Materijali po predmetima →</a></aside><div class="resource-list"><?php while(have_posts()) : the_post(); $url=get_post_meta(get_the_ID(),'_matinf_fileUrl',true); ?><article class="resource-row"><span class="file-symbol" aria-hidden="true">↓</span><div><span class="eyebrow">DOKUMENT</span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(matinf_excerpt(get_post(),18)); ?></p><div class="resource-actions"><a href="<?php the_permalink(); ?>">Detalji →</a><?php if($url) : ?><a class="outline-link" href="<?php echo esc_url($url); ?>">Otvori datoteku ↗</a><?php endif; ?></div></div></article><?php endwhile; if(!$GLOBALS['wp_query']->post_count) echo '<p class="empty">Dokumenti još nisu objavljeni.</p>'; ?></div></div><?php matinf_theme_pagination();
} elseif($is_notices) {
    matinf_theme_heading('Sve važno za vaš dan.','Obavještenja o nastavi, ispitima, materijalima i aktivnostima akademske zajednice.','OBAVJEŠTENJA'); ?>
    <div class="bulletin-layout"><div class="bulletin-list"><?php while(have_posts()) : the_post(); $important=(bool)get_post_meta(get_the_ID(),'_matinf_important',true); ?><article class="bulletin-row"><time class="date-block" datetime="<?php echo esc_attr(get_the_date('c')); ?>"><strong><?php echo esc_html(get_the_date('d')); ?></strong><span><?php echo esc_html(get_the_date('m. Y.')); ?></span></time><div><span class="tag <?php echo $important?'important':''; ?>"><?php echo $important?'Važno':'Obavještenje'; ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(matinf_excerpt(get_post(),24)); ?></p><a class="read-more" href="<?php the_permalink(); ?>">Pročitajte obavještenje →</a></div></article><?php endwhile; if(!$GLOBALS['wp_query']->post_count) echo '<p class="empty">Trenutno nema obavještenja.</p>'; ?></div><aside class="section-aside"><p class="eyebrow">VAŠ AKADEMSKI DAN</p><h2>Planirajte na vrijeme.</h2><p>Provjerite termine nastave i ispita za svoj program i godinu.</p><a class="button" href="<?php echo esc_url(home_url('/raspored/')); ?>">Otvori raspored →</a><hr><h3>Pronađite svoj predmet</h3><a href="<?php echo esc_url(get_post_type_archive_link('mf_course')); ?>">Pregled predmeta →</a></aside></div><?php matinf_theme_pagination();
} else {
    matinf_theme_heading(is_category()?single_cat_title('',false):'Novosti','Priče, ideje i dešavanja iz naše akademske zajednice.','AKTUELNO NA MATINF-U');
    $posts=$GLOBALS['wp_query']->posts; $featured=array_shift($posts); ?>
    <div class="news-layout"><div><?php if($featured) : ?><article class="featured-story"><a class="feature-link" href="<?php echo esc_url(get_permalink($featured)); ?>"><?php matinf_theme_visual($featured); ?><div class="featured-copy"><span class="tag">Najnovije</span><time><?php echo esc_html(get_the_date('d. m. Y.',$featured)); ?></time><h2><?php echo esc_html(get_the_title($featured)); ?></h2><p><?php echo esc_html(matinf_excerpt($featured,25)); ?></p><span>Pročitajte priču ↗</span></div></a></article><?php endif; ?><div class="editorial-grid"><?php foreach($posts as $entry) matinf_theme_post_card($entry); ?></div><?php if(!$featured) echo '<p class="empty">Novosti još nisu objavljene.</p>'; ?></div><aside class="news-sidebar"><p class="eyebrow">NE PROPUSTITE</p><h2>Najnovija obavještenja</h2><?php foreach(get_posts(['post_type'=>'post','post_status'=>'publish','has_password'=>false,'category_name'=>'obavjestenja','numberposts'=>5]) as $entry) : ?><a class="sidebar-news" href="<?php echo esc_url(get_permalink($entry)); ?>"><time><?php echo esc_html(get_the_date('d. m.',$entry)); ?></time><strong><?php echo esc_html(get_the_title($entry)); ?></strong><span>→</span></a><?php endforeach; ?></aside></div><?php matinf_theme_pagination();
}
